def group_tuples(Input):
    """Write a function to find common first element in given list of tuple.

    Group tuples that share the same first element into a single tuple,
    preserving the order in which each first element first appears and
    the order of the remaining elements within each group. Tuples with
    more than two elements contribute all of their remaining elements.
    An empty input returns an empty list, and the input is not mutated.
    """
    groups = []
    keys = []

    for item in Input:
        item_tuple = tuple(item)
        if not item_tuple:
            # An empty tuple has no first element to group by; keep it
            # as its own group. A unique key prevents merging empties.
            keys.append(object())
            groups.append([])
            continue

        key = item_tuple[0]
        for index, existing_key in enumerate(keys):
            if existing_key == key:
                groups[index].extend(item_tuple[1:])
                break
        else:
            keys.append(key)
            groups.append(list(item_tuple))

    return [tuple(group) for group in groups]
